
-- Batch 2: Asia missing recipes
INSERT INTO public.recipes (name, slug, country, continent, category, difficulty, prep_time, cook_time, servings, summary, history, ingredients, steps, tags, image_url) VALUES
('Mongolian Beef', 'mongolian-beef-mongolia', 'Mongolia', 'Asia', 'Main Course', 'Medium', 20, 15, 4, 'Crispy sliced beef in a sweet and savory soy-ginger sauce with scallions.', 'Despite its name, Mongolian Beef was created in Taiwanese BBQ restaurants. It draws inspiration from Mongolian grilling traditions but is a modern Asian fusion dish.', '["1.5 lbs flank steak, sliced thin","1/4 cup cornstarch","3 tbsp vegetable oil","4 cloves garlic, minced","1 tsp ginger, grated","1/2 cup soy sauce","1/2 cup brown sugar","1/2 cup water","1 bunch scallions, cut into 2-inch pieces","Steamed rice for serving"]'::jsonb, '["Toss sliced beef in cornstarch until coated","Heat oil in a wok over high heat","Sear beef in batches until crispy, about 2 minutes per side","Remove beef and sauté garlic and ginger for 30 seconds","Add soy sauce, brown sugar, and water; bring to a simmer","Return beef to wok and toss to coat","Add scallions and cook 1 minute more","Serve immediately over steamed rice"]'::jsonb, ARRAY['Asian','Fusion','Beef','Stir-Fry'], 'https://images.unsplash.com/photo-1603073163308-9654c3fb70b5?w=800'),

('Xiaolongbao', 'xiaolongbao-china', 'China', 'Asia', 'Appetizer', 'Hard', 60, 15, 4, 'Delicate soup dumplings filled with pork and rich broth, a Shanghai specialty.', 'Xiaolongbao originated in the Nanxiang district of Shanghai in the 19th century. These intricate dumplings require exceptional skill to create the thin wrapper that holds both meat filling and hot soup.', '["2 cups all-purpose flour","3/4 cup boiling water","1 lb ground pork","2 cups pork or chicken aspic (gelled broth)","2 tbsp soy sauce","1 tbsp sesame oil","1 tbsp Shaoxing wine","1 tsp ginger, minced","2 scallions, minced","Black vinegar and ginger for dipping"]'::jsonb, '["Make dough with flour and boiling water, knead until smooth, rest 30 min","Chop aspic into small cubes","Mix pork with soy sauce, sesame oil, wine, ginger, scallions","Fold in aspic cubes gently","Divide dough into 24 pieces, roll into thin wrappers","Place filling in center, pleat edges to seal (18-20 folds)","Steam in bamboo steamer over boiling water for 8-10 minutes","Serve immediately with black vinegar and ginger"]'::jsonb, ARRAY['Chinese','Shanghai','Dumplings','Dim Sum','Steamed'], 'https://images.unsplash.com/photo-1496116218417-1a781b1c416c?w=800'),

('Bibimbap', 'bibimbap-korea', 'South Korea', 'Asia', 'Main Course', 'Medium', 30, 20, 4, 'A colorful Korean rice bowl topped with sautéed vegetables, meat, a fried egg, and gochujang.', 'Bibimbap means "mixed rice" in Korean and dates back to the Joseon dynasty. It was originally a way to use leftover side dishes by mixing them with rice, evolving into one of Korea''s most iconic dishes.', '["4 cups steamed rice","200g beef sirloin, sliced thin","2 carrots, julienned","1 zucchini, julienned","200g spinach, blanched","200g bean sprouts, blanched","4 eggs","4 tbsp gochujang","2 tbsp sesame oil","2 tbsp soy sauce","Sesame seeds"]'::jsonb, '["Marinate beef in soy sauce and sesame oil for 15 minutes","Sauté each vegetable separately with a pinch of salt and sesame oil","Cook marinated beef until browned","Fry eggs sunny-side up","Divide rice among 4 bowls","Arrange vegetables, beef, and egg on top of rice","Add a generous spoonful of gochujang","Drizzle with sesame oil, sprinkle sesame seeds","Mix everything together before eating"]'::jsonb, ARRAY['Korean','Rice Bowl','Healthy','Colorful'], 'https://images.unsplash.com/photo-1553163147-622ab57be1c7?w=800'),

('Hot Pot', 'hot-pot-china', 'China', 'Asia', 'Main Course', 'Easy', 30, 60, 6, 'A communal dining experience where diners cook fresh ingredients in a bubbling pot of seasoned broth.', 'Hot pot has over 1,000 years of history in China, originating in Mongolia as a way for warriors to cook on horseback. Sichuan hot pot, with its fiery mala broth, became the most popular variation.', '["8 cups chicken or bone broth","2 tbsp Sichuan peppercorns","4 tbsp chili oil","Thinly sliced beef and lamb","Firm tofu, cubed","Napa cabbage, sliced","Enoki mushrooms","Rice noodles","Bok choy","Dipping sauces: sesame paste, soy sauce, garlic"]'::jsonb, '["Prepare broth by simmering stock with peppercorns and aromatics","Arrange all raw ingredients on platters around the table","Bring broth to a rolling boil in a hot pot at the center of the table","Each diner cooks their chosen ingredients in the broth","Leafy greens take 30 seconds, meat slices 1-2 minutes","Noodles and tofu take 3-5 minutes","Dip cooked items in prepared sauces","Continue cooking and eating communally"]'::jsonb, ARRAY['Chinese','Communal','Interactive','Sichuan'], 'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?w=800'),

('Rendang', 'rendang-indonesia', 'Indonesia', 'Asia', 'Main Course', 'Hard', 30, 180, 8, 'A rich, slow-cooked dry curry of beef simmered in coconut milk and a complex spice paste.', 'Rendang originated with the Minangkabau people of West Sumatra. In 2011, CNN named it the most delicious food in the world. It was traditionally prepared for ceremonial occasions and to preserve meat for long journeys.', '["2 lbs beef chuck, cubed","2 cans coconut milk","1 cup desiccated coconut, toasted","10 dried chilies, soaked","8 shallots","6 cloves garlic","2 inches galangal","2 inches ginger","3 stalks lemongrass","6 kaffir lime leaves","2 turmeric leaves (optional)","Salt and sugar to taste"]'::jsonb, '["Blend chilies, shallots, garlic, galangal, and ginger into a paste","Bruise lemongrass stalks","Cook spice paste in a large pot until fragrant, about 10 minutes","Add beef and stir to coat with paste","Pour in coconut milk and add lemongrass, lime leaves","Bring to a boil then reduce to a gentle simmer","Cook uncovered for 2.5-3 hours, stirring occasionally","Add toasted coconut when liquid has mostly evaporated","Continue cooking until meat is dark, tender, and coated in thick sauce"]'::jsonb, ARRAY['Indonesian','Minangkabau','Curry','Slow-Cooked','CNN #1'], 'https://images.unsplash.com/photo-1606491956689-2ea866880049?w=800'),

('Laksa', 'laksa-malaysia', 'Malaysia', 'Asia', 'Soup', 'Medium', 25, 30, 4, 'A spicy coconut curry noodle soup with prawns, tofu puffs, and fresh herbs.', 'Laksa represents the fusion of Chinese and Malay cuisines in Southeast Asia. Curry laksa uses coconut milk while assam laksa uses tamarind. It''s a beloved street food across Malaysia and Singapore.', '["400g rice noodles","1 can coconut milk","3 cups chicken stock","4 tbsp laksa paste","200g prawns, peeled","4 tofu puffs, halved","100g bean sprouts","2 hard-boiled eggs, halved","Fresh mint and cilantro","Sambal for serving","Lime wedges"]'::jsonb, '["Cook rice noodles according to package directions, drain","Heat laksa paste in a pot until fragrant","Add coconut milk and chicken stock, bring to a simmer","Add prawns and cook for 3-4 minutes until pink","Add tofu puffs and heat through","Divide noodles among bowls","Ladle hot laksa broth over noodles","Top with bean sprouts, egg halves, fresh herbs","Serve with sambal and lime wedges"]'::jsonb, ARRAY['Malaysian','Noodle Soup','Coconut','Spicy','Street Food'], 'https://images.unsplash.com/photo-1569562211093-4ed0d0758f12?w=800'),

('Hainanese Chicken', 'hainanese-chicken-singapore', 'Singapore', 'Asia', 'Main Course', 'Medium', 20, 60, 4, 'Perfectly poached chicken served with fragrant rice cooked in chicken fat and broth.', 'Hainanese Chicken Rice was brought to Southeast Asia by immigrants from Hainan, China. It became Singapore''s unofficial national dish, with hawker stalls competing fiercely for the best version.', '["1 whole chicken (3-4 lbs)","3 cups jasmine rice","Chicken fat and skin (reserved)","4 cloves garlic, minced","2 inches ginger, sliced","2 pandan leaves","Chicken broth for cooking rice","Soy sauce, chili sauce, ginger sauce for dipping","Cucumber slices","Fresh cilantro"]'::jsonb, '["Rub chicken with salt, stuff cavity with ginger and scallions","Poach chicken in boiling water, then ice bath method for silky texture","Reserve poaching liquid as broth","Render chicken fat in a pan, sauté garlic and ginger","Cook rice in chicken fat with broth and pandan leaves","Chop chicken into pieces","Arrange on plate with cucumber and cilantro","Serve rice alongside with three dipping sauces","Ladle hot broth into small bowls as soup"]'::jsonb, ARRAY['Singaporean','Hainanese','Chicken','Rice','Hawker'], 'https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?w=800'),

('Amok', 'amok-cambodia', 'Cambodia', 'Asia', 'Main Course', 'Medium', 30, 25, 4, 'A Cambodian fish curry steamed in banana leaves with coconut cream and kroeung spice paste.', 'Fish amok is Cambodia''s national dish, dating back to the Khmer Empire. The kroeung paste at its base is the foundation of Cambodian cooking, combining lemongrass, galangal, turmeric, and makrut lime.', '["500g white fish fillet, cubed","1 can coconut cream","3 tbsp kroeung paste","2 eggs, beaten","1 tbsp fish sauce","1 tsp sugar","Banana leaves for steaming","Napa cabbage leaves","Sliced red chili for garnish","Fresh Thai basil","Kaffir lime leaves, shredded"]'::jsonb, '["Mix kroeung paste with coconut cream, reserving some cream for topping","Add fish sauce, sugar, and beaten eggs","Fold in cubed fish gently","Line banana leaf cups with cabbage leaves","Spoon fish mixture into banana leaf cups","Top with reserved coconut cream and lime leaf shreds","Steam for 20-25 minutes until set","Garnish with red chili and Thai basil","Serve with steamed jasmine rice"]'::jsonb, ARRAY['Cambodian','Khmer','Fish','Curry','Steamed'], 'https://images.unsplash.com/photo-1455619452474-d2be8b1e70cd?w=800'),

('Larb', 'larb-thailand', 'Thailand', 'Asia', 'Salad', 'Easy', 15, 10, 4, 'A zesty Thai minced meat salad with herbs, lime, fish sauce, and toasted rice powder.', 'Larb originated in Laos and northeastern Thailand (Isan region). It''s considered the national dish of Laos. The toasted rice powder gives it a distinctive nutty crunch that defines the dish.', '["1 lb ground pork or chicken","3 tbsp fish sauce","3 tbsp lime juice","1 tbsp toasted rice powder","4 shallots, thinly sliced","Fresh mint leaves","Fresh cilantro","Scallions, sliced","1-2 tbsp chili flakes","Lettuce leaves for serving"]'::jsonb, '["Toast raw rice in a dry pan until golden, then grind to powder","Cook ground meat in a pan, breaking it up, until just done","Remove from heat immediately","Toss meat with fish sauce, lime juice, and chili flakes","Add shallots, mint, cilantro, and scallions","Sprinkle with toasted rice powder and toss","Serve on lettuce leaves","Accompany with sticky rice and raw vegetables"]'::jsonb, ARRAY['Thai','Isan','Salad','Spicy','Healthy'], 'https://images.unsplash.com/photo-1562565652-a0d8f0c59eb4?w=800'),

('Satay', 'satay-indonesia', 'Indonesia', 'Asia', 'Appetizer', 'Easy', 30, 15, 6, 'Grilled skewered meat served with a rich peanut dipping sauce, a Southeast Asian classic.', 'Satay likely originated in Java, Indonesia, inspired by Indian kebab traditions brought by Muslim traders. It spread throughout Southeast Asia and is now a beloved street food across the region.', '["1.5 lbs chicken thighs, cubed","Bamboo skewers, soaked","2 tbsp soy sauce","1 tbsp turmeric","1 tbsp coriander","2 tbsp brown sugar","Peanut Sauce: 1/2 cup peanut butter, 2 tbsp soy sauce, 1 tbsp lime juice, 1 tbsp chili sauce, 2 tbsp coconut milk","Cucumber and onion for serving"]'::jsonb, '["Marinate chicken in soy sauce, turmeric, coriander, and sugar for 1 hour","Thread onto soaked bamboo skewers","Make peanut sauce by mixing all sauce ingredients until smooth","Grill skewers over high heat for 3-4 minutes per side","Baste with remaining marinade while grilling","Serve with peanut sauce, cucumber, and red onion","Squeeze lime over before eating"]'::jsonb, ARRAY['Indonesian','Street Food','Grilled','Peanut Sauce','Skewers'], 'https://images.unsplash.com/photo-1529563021893-cc83c992d75d?w=800');
